#include "synthetic_motion.hpp"
#include <cstdint>
#include <iostream>
#include <limits>
int main() {
    preview::SyntheticMotionAdapter adapter;
    for (unsigned i = 0; i < 100; ++i) {
        if (!adapter.shake()) {
            std::cerr << "FAIL default or repeated fixture at request " << i << '\n';
            return 1;
        }
    }
    std::cout << "PASS: 100 persistent fixture requests each emit exactly one event\n";
    preview::SyntheticMotionAdapter wrapping(std::numeric_limits<std::uint32_t>::max() - 1000);
    for (unsigned i = 0; i < 100; ++i) {
        if (!wrapping.shake()) {
            std::cerr << "FAIL unsigned-clock-wrap fixture at request " << i << '\n';
            return 1;
        }
    }
    std::cout << "PASS: virtual clock wrap and 100 further fixture requests\n";
}
